import{_ as s,c as t,o as n,j as a,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"漢上先生履歷","description":"漢上易傳 - 漢上先生履歷","frontmatter":{"title":"漢上先生履歷","description":"漢上易傳 - 漢上先生履歷"},"headers":[],"relativePath":"classics/hanshang/013.md","filePath":"classics/hanshang/013.md"}'),l={name:"classics/hanshang/013.md"};function c(o,e,i,d,p,h){return n(),t("div",null,[...e[0]||(e[0]=[a("h1",{id:"漢上先生履歷",tabindex:"-1"},[r("漢上先生履歷 "),a("a",{class:"header-anchor",href:"#漢上先生履歷","aria-label":"Permalink to “漢上先生履歷”"},"​")],-1),a("p",null,"除春秋博士告詞：敕迪功郎朱震：孔子曰：吾志在春秋。又曰：知我者其惟春秋乎。是經之不用於世，果遵何說哉？朕比詔立學官，用以取士，命汝往處師席。爾其推明三家之同異，與諸生切磨，以求合於聖人之意，罔俾漢儒專以名家，則稱朕旨。可特授依前官守太學春秋博士。靖康元年五月九日，除太學春秋博士告詞：敕宣教郎朱震：孔子作春秋而亂臣賊子懼，豈特當時為然，使千百載之後猶凜然畏之，此經所以久鬱而不明也。朕比命列子博士訓迪諸生，爾以修潔該洽而膺是選，必能明聖人作經之旨，使學者有考焉。勉稱厥職，予則汝嘉。可特授依前宣教郎、太學春秋博士填見闕。靖康元年十月二十日除秘書郎告詞。敕：宣教郎、太學博士朱震中：秘讎書極天下豪俊之選，異時貴臣用事，至參用醫卜之流，牛驥同群，可為太息。肆朕初載，遴柬儒術之英。爾以文藝有聞，首置茲選。進與群髦之列，益觀未見之書。三篋巳亡，且詢安世。勉思刻厲，將有試焉。可特授依前宣教郎、秘書省校書郎。靖康元年十一月六日，除祠部員外郎。告詞。敕：左宣教郎朱震：朕旁求俊乂，列置文昌，非徒使之分職率屬，允釐庶事。而眾正在位，則朝廷自尊。爾涉道精淳，存心樂易，強學力行，白首不衰。聞望之休，溢於予聽。嘉其敷奏之美，喜見德人之容。郎選甚高，祠曹務簡。往共乃職，體朕眷私。可特授依前官守尚書祠部員外郎。紹興四年十月五日除秘書少監告詞。敕左奉議郎、守尚書祠部員外郎朱震。朕惟否泰二卦，論君子小人消長之理甚明。或者謂消長系乎時數，此大不然。上下交而其志同，於時為泰，故君子以其匯徵。上下不交而天下無邦，於時為否，故君子以儉德避難而巳。爾學古通經，特立守正，粹然君子人也，固窮鄉閭，累經除召。今者惠然肯來，就我榮祿。朕以爾之避就，卜時否泰，其庶幾焉。蓬山寶藏，乃今日養才之地也，用爾為貳，蓋不徒然。朕知爾舊矣，奚俟深訓。可特授依前官試秘書少監。紹興五年二月十六日，除秘書少監兼侍講告詞。左奉議郎、試秘書少監朱震可特授依前左奉議郎、試秘書少監、兼侍講、左朝奉大夫、守宗正少卿、兼直史館範衝等：學之為王者事，其巳久矣。雖二帝三王，蓋嘗汲汲於此。朕於國家多艱之際，不廢祖宗故事，爰命儒學之臣，環侍便坐，講經史，敷求政禮，以廣聰明。爾等操履端方，學問該洽，通今古，達於治亂之原，其必有裨。吾不逮宜，自卿監之聯，兼陪經幄之職，益思報稱，以副旁求。可依前件。紹興五年閏二月五日轉承議郎告詞。敕左奉議郎、試秘書少監兼侍講朱震：朕纂極之初，推曠蕩之澤，士大夫京秩而上，例進一等，蓋祖宗舊制也。爾方投閒在遠，積有歲年，而恩未沾及，恬退之風，有足嘉者。序進厥官，往其祗服。可特授左承議郎，依前秘書少監兼侍講。紹興五年三月九日除起居郎。告詞：敕左承議郎、秘書少監兼侍講朱震：孔子稱天下歸仁，曰：非禮勿言，非禮勿動。人君託於王公之上，一言一動，則必記之。是欲克巳復禮，俾天下之歸也。設官之意，其深矣乎！以爾習於春秋，明乎褒貶，經筵勸講，開益為多。命爾立螭，記予言動。官分左右，職固不殊。朕知戒非禮之為，爾其謹必書之職。可特授依前左承議郎、守起居郎、兼侍講。紹興五年五月三日，除兼資善堂贊讀告詞。敕左承議郎、守起居郎、兼侍講、賜緋魚袋朱震：朕惟蒙之",-1),a("p",null,"象曰：山下出泉，蒙，君子以果行育德。蓋泉之初，未有所之，如人之蒙，未知所適。泉決之東西，蒙導之邪正。亦惟其人而巳矣。以爾純白內備。博見洽聞。羲易麟經。尤所精貫。華光勸講。宏益滋多。方開學於南宮。久注心於舊德。贊讀資善。汝往惟諧。既正朕之不難。宜誨蒙之無倦。兼職雖眾。應用莫窮。勿嫌拜賜之頻。實繄稽古之力。其益懋哉。可特授依前官兼侍講兼資善堂贊讀。紹興五年六月三日除中書舍人兼資善堂翊善告詞。敕：昔者周穆繼南征之後，無討賊之心。逮乎平王為東遷之君，無興復之志。觀其告命，泰然與成康之世無異，君子是以知周德之衰矣。烏乎。有能宣吾惻怛難喻之情，如建武奉天詔書，以助中興之功者乎？左朝奉郎、守起居郎、兼侍講、兼資善堂贊讀、賜緋魚袋朱震，學博而造深，行和而志正，以道獻替，簡於朕心。升擢綸誥之司，仍卒金華之業，尚賢西學，諭教如初。夫士以得君為難，而朕之知汝者厚矣。論思潤色，尚往欽哉。必無媿於古人，乃有辭於永世。可特授依前官、試中書舍人、兼侍講、兼資善堂翊善。紹興五年八月十七日，轉朝散郎。告詞。敕：典謨訓誥，皆上古之書；筆削春秋，著先王之志。其文雖史，垂世為經。朕仰奉孫謀，恭繩祖武。覽裕陵之實錄，悼私史之謗言。譬夫氛祲之興，或掩昭回之象。乃詔群彥，同次舊文。左朝奉郎、試中書舍人兼侍講，兼資善堂翊善、賜紫金魚袋朱震，學貫九流，趨皇極會歸之要；識深五傳，窮古人述作之原。頃預編摩，克嚴去取，茲閱奏篇之上，彌嘉汗簡之勞。十九年之勳德既昭，千萬世之楷模斯在。祖宗有慶，非出朕私，爵秩所加，式為爾寵。名附不刊之典，實彰有永之辭。可特授左朝散郎，依前試中書舍人。紹興五年十月七日，轉左朝請郎告詞。敕：朕惟帝王之治，求端於天。是以察璇璣者協時月正日，陳洪範者省歲月日時。本天理而時措之，后王用智力而持世曲學，判天人為兩途。凡曆象授民之妙，散為術家。至於閏餘失次，攝提無紀，以為是固然，而不知其拂天害民，亂之大者也。左朝散郎、試中書舍人、兼侍講、兼資善堂翊善、賜紫金魚袋朱震，學深象數，智潛幽眇，會於道要，得其本原。屬曆法之有差，視筭家而參正。成書來上，七政以齊。雖史遷之起太初，子云之明三統，不得專美，予用嘉之。序進一官，少旌勞績，是謂德賞，往其欽承。可特授左朝請郎，餘依前。紹興五年十月二十二日除給事中告詞。敕：自昔有事殿內之臣，不過侍左右、掌顧問而巳，然猶遴擇名儒，以充此選。矧今萬務出入，皆屬東臺，時當艱危，動關興廢。其或行事不協於中，任官不厭於眾，雖有君命，皆得駮而正之，其職可謂重矣。肆求聞人，今以命汝。左朝請郎、試中書舍人兼侍講、兼資善堂翊善，賜紫金魚袋朱震，學際天人，識窮理亂，年德俱懋，望實素隆。演誥西垣，榮問益暢，進司瑣闥，公議允諧。夫糾其乖違，俾庶政孚於群聽；審其奏述，使下情得而上通，則朕為得人，而汝為稱職，豈不休哉！可特授依前左朝請郎、試給事中，餘如故。紹興六年正月十六日，轉左朝奉大夫告詞：敕：朕深惟國本，茂建宗支。朝夕端士之親，冀性習於為善；博約前言之識，俾學富於多聞。聿就終篇，可無褒律。翰林學士、左朝請郎、知制誥、兼侍讀、兼資善堂翊善、賜紫金魚袋朱，　心潛六藝，文貫九流。廷論倚如蓍龜，正人賴為領袖。雍容視草，何獨潤色之工；密勿告猷，備罄論思之益。屬宗藩之諭教，嘉術業之向成。疇稽古之勤，既車服之是錫。懋增秩之渥，抑典故之具存。尚堅調護之功，用究師儒之效。眷予耆艾，奚假訓詞。可特授左朝奉大夫，依前翰林學士、知制誥，餘如故。紹興六年十一月三日，乞宮觀差遣不允。詔敕：朱　省札子奏乞除一在外宮勸差遣事，具悉。朕以王教存乎篇籍，方儒學之是諮；老成重於典刑，實朝廷之所賴。故詳延於瑰碩，以參劘於古今。卿道術深明，文辭英妙。耆名高義，足以為群士之羽儀；博物洽聞，足以備一時之訪問。禁林遞直，歲律載周。侍經幄之燕間，謹宗藩之訓導。國僑潤色，非有官職之甚勞；陸䞇腹心，尚倚神明之克壯。奉身而退，匪朕所聞，其體眷懷，母重來請所請宜不允，仍不得再有陳請。故茲詔示，想宜知悉。再乞宮觀，不允。詔：卿文足以達意，學足以明理，行足以正人。兼是三者，故處以視草橫經之地，且使從吾嗣子之遊，既有年矣。遽覽奏章，引疾丏外，辭意甚切，朕為之動心焉。夫德齒俱懋，固平日之所尊；氣體失平，亦老者之常事。姑務休養，以期清明，使朝廷之所寶惟賢，則四方必仰朕之德，豈小補哉！所請宜不允。故茲詔示，想宜知悉。辭免翰林學士。不允。詔敕：朱　省所奏辭免翰林學士、知制誥恩命事，具悉。昔陸䞇為學士，國有大政，參裁可否，興元戡難之功，實多文懷之助。卿學造壼域，識通系表，文章典雅，無愧昔人，議論堅明，有補當世。越朕初載，杖策軍門，誼先國家，節貫華皓。老成在服，厥有典刑。俾代予言，以紓素縕。豈特資其討論潤色之益，亦將託以腹心耳目之寄焉。尚執謙撝，殆非所望。亟共乃服，母復費辭。所請宜不允。故茲詔示，想宜知悉。再乞宮觀，不允。詔敕朱　乞除在外宮觀事，具悉。卿學高諸儒，名映一代。從朕艱難之際，實惟舊人。藹然德義之風，信於多士。契闊累歲，登崇近班。大冊高文，佐時戡難。博物強記，益朕多聞。國有老成，眾無異論。朕方知九德之行，灼見三俊之心，庶無遺材，用齊多故。雖山林隱居之士，尚當結綬而來；顧朝廷領袖之賢，乃欲奉身而去。況神明之克壯，何疾病之可言。覽觀來章，殊咈朕眷。勉安厥位，母復有云。所請宜不允。故茲詔示，想宜知悉。辭免建國公、聽讀尚書終篇恩命不允。詔：𢽟朱　所奏辭免轉一官恩命事具悉。朕擇本支以隆國勢，修勸導而備官司，其有成勞，可無褒命。卿經術深懿，獨高諸儒，德性純明，自傾多士。為時耆舊，適副簡求，日陳道義之言，助子詩、禮之訓。肆稽故事，以寵畢章。朕方擢先王厲世之規，通天下赴功之志，雖疏遠之吏，摽末之庸，並錄不遺，以勸為善。況如卿者，其可辭乎？何為上書，遽求反令，固難曲徇其趣。欽承所請。宜不允。再辭，不允。詔：朕以卿道藝深明，行能高妙，傳授經業，訓迪宗藩。俾通上古之書，宜從增秩之賞。而乃屢陳悃愊，力避寵榮。夫尊賢顯功，蓋人主馭臣之柄；而難進易避，亦師儒厲俗之規。使勤勞而見知者尚或固辭，則虛偽而倖進者庶幾有恥。豆惟勉從於爾志，抑亦少勸於士風。載亮沖懷，不忘嘉嘆。乞宮觀。不允。詔：朕寤懷英賢，共圖康濟。雖山林隱逸之士，尚不倦於招徠；矧朝廷耆艾之儒，豈忍使其輕去。卿學窮聖域，行允廷僉，論必據經，文推華國。揚，歷禁塗之久，備觀辰告之忠。不獨朕知卿之既深，亦惟卿守義之甚固。老成在列，多士朋來，胡為抗章，遽欲引退。與其潔身而辭位，希廉士之風；熟若盡道以致君，卒賢人之業。勉體至意，母重有陳。所請宜不允贈官告詞。𢽟！死生之道，通乎晝夜，達者以為當然；君臣之義，篤於始終，有國以為令典。逮此告終之問，敢忘哀贈之恩。故翰林學士、左朝奉大夫致仕、長林縣開國男、食邑三百戶、賜紫金魚袋朱，　蚤以詞華，亟躋脢仕，晚由學術，薦更禁塗。驚怛化之無常，悵徽音之如在，子有憖遺之感，人懷殄瘁之悲。考於故常，申此贈典。百身可贖，興懷不朽之規；一鑑雲亡，徒有無從之涕。精爽不昧，宜歆此恩。可特贈左中大夫，餘如故。紹興八年七月三日回。朱八行子發啟。　　　　　胡文定公 安國。 薦章交剡，公議甚孚。凡屬俊遊，共欣榮問。學正八行賦才雄驁，受業精通。手披萬卷之書，要歸卓約；筆掃千軍之陣，恥尚浮華。有言必務於躬行，所得多繇於心了。家庭素履，豈求聞達之方。郡國諸侯，樂任賓興之職。夜鶴不驚於佩帳，大鵬正假於扶搖。言念迂愚，久敦情好。論交莫逆，固蘄美譽之彰；懲沸誤吹，初絕遊談之助。盍相忘於微笑，尚伸貺於長箋。過形引重之詞，彌服推先之義。然賢者名高而責備，物情利及而爭歸。聖門之實學難窮，人境之虛榮易惑。平居把袂，最欽松桂之姿。得路彯纓，更礪冰霜之節。證明吾道，倚仗英摽。祭文：維紹興八年歲次戊午七月庚申朔十七日辛丑，左朝散郎、試尚書吏部侍郎、兼詳定一司𢽟令晏敦復、左朝散大夫、試尚書戶部侍郎、兼詳定一司𢽟今李彌遜，左中大夫、試尚書禮部侍郎曾開，左朝請郎、試尚書兵部侍郎張燾，左朝奉大夫、新除尚書兵部侍郎、兼資善堂翊善、兼侍講吳圭，左朝奉大夫、試給事中兼侍講張致遠，左朝奉大夫試給事中兼史館修撰勾濤，左朝奉郎試中書舍人兼直學士院兼侍講呂本中，左朝請郎試中書舍人樓炤，左朝請郎試中書舍人勾龍如淵、左朝請郎權尚書吏部侍郎魏玒，左奉議郎權禮部侍郎張九成，謹以清酌庶羞之奠，致祭於故侍讀內翰翊善朱公之靈。惟公老於田畝，困於州縣，白首窮經，意則不倦。視彼世人，奚貴奚賤。不義而得，吾亦不願。一昨召來，遇知明主。金馬玉堂，四涉寒暑。以經決事，隨事有補。位高職卑，亦莫公侮。不傳之要，自得之妙。惟公知之，固世所笑。彼笑何傷，公亦自強。愈老愈壯，雖死不亡。識公日淺，相知則深。公病不起，孰不痛心。涼風應時，白露日侵。薄酒寓哀，公或肯臨。尚饗。",-1),a("p",null,"宋朱震撰。按震表進是書，謂馬、鄭、荀、虞各自名家，說雖不同，去象數之源未遠。獨魏王弼盡去舊說，雜以莊、老之言，於是儒者專尚文辭，不復推原大傳，天人之道，分裂不合。又歷舉宋世諸儒宗旨，謂或明其象，或論其數，或傳其辭，或兼而明之。復自稱獲觀遺書，粗窺一二，撰為是書，以易傳為宗，和會雍載之論，上採漢、魏、吳、晉、元魏，下逮有唐及今，包括異同，補苴罅漏云云。其後諸儒評論，互有褒貶，或譏其謬妄，或謂其不可廢。四庫著錄通志堂經解，亦經採刊。惟均附卦圖三卷、叢說一卷，是為南宋舊刊。影自北平圖書館，存易傳九卷，佚卷一、二及卷五若干葉。補以毛氏汲古閣影抄本。按文淵閣書目載是書一部三冊，一部十冊，均闕，毛氏影抄，亦佚卦圖叢說。蓋宋本散佚已久，今不可復見，且集傳首尾完具，故影印之，以餉世之嗜讀古書者。民國紀元二十三年十月，海鹽張元濟",-1)])])}const f=s(l,[["render",c]]);export{_ as __pageData,f as default};
